import * as THREE from 'three';

// Small painter-based 3D fallback for browsers without a WebGL context.
// Uses the SAME meshes, camera, picking, and orbit controls as the GPU renderer.
export class SoftwareRenderer {
 constructor(){this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d',{alpha:true});this.cache=new WeakMap();this.width=1;this.height=1;this.ratio=1;this.software=true;this.lastFrame=0;this.matrix=new THREE.Matrix4();this.modelView=new THREE.Matrix4();this.normal=new THREE.Matrix3();this.v=new THREE.Vector3();}
 setPixelRatio(r){this.ratio=Math.min(r,1.15)}
 setClearColor(){}
 setSize(w,h){this.width=w;this.height=h;this.domElement.width=Math.round(w*this.ratio);this.domElement.height=Math.round(h*this.ratio);this.domElement.style.width=w+'px';this.domElement.style.height=h+'px'}
 geometryData(g){let cached=this.cache.get(g);if(cached)return cached;const p=g.attributes.position.array,n=g.attributes.normal?.array,indices=g.index?.array||Array.from({length:p.length/3},(_,i)=>i);const triangles=[];for(let i=0;i<indices.length;i+=3){const a=indices[i]*3,b=indices[i+1]*3,c=indices[i+2]*3;triangles.push([a,b,c,n?(n[a]+n[b]+n[c])/3:0,n?(n[a+1]+n[b+1]+n[c+1])/3:1,n?(n[a+2]+n[b+2]+n[c+2])/3:0]);}cached={p,triangles,projected:new Float32Array(p.length)};this.cache.set(g,cached);return cached;}
 render(scene,camera){const now=performance.now();if(now-this.lastFrame<85)return;this.lastFrame=now;scene.updateMatrixWorld();camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const ctx=this.ctx,w=this.width,h=this.height,faces=[];const light=new THREE.Vector3(-.4,.65,.65).normalize();
 scene.traverseVisible(mesh=>{if(!mesh.isMesh||!mesh.material||mesh.material.opacity<.01)return;const mat=mesh.material,g=this.geometryData(mesh.geometry),p=g.p,out=g.projected;this.modelView.multiplyMatrices(camera.matrixWorldInverse,mesh.matrixWorld);this.matrix.multiplyMatrices(camera.projectionMatrix,this.modelView);const m=this.matrix.elements;this.normal.getNormalMatrix(this.modelView);const nm=this.normal.elements;const color=mat.color.clone().convertLinearToSRGB();
 for(let i=0;i<p.length;i+=3){const x=p[i],y=p[i+1],z=p[i+2],ww=1/(m[3]*x+m[7]*y+m[11]*z+m[15]);out[i]=(m[0]*x+m[4]*y+m[8]*z+m[12])*ww*w*.5+w*.5;out[i+1]=-(m[1]*x+m[5]*y+m[9]*z+m[13])*ww*h*.5+h*.5;out[i+2]=(m[2]*x+m[6]*y+m[10]*z+m[14])*ww;}
 const op=mat.opacity;for(const [a,b,c,nx,ny,nz]of g.triangles){const ax=out[a],ay=out[a+1],bx=out[b],by=out[b+1],cx=out[c],cy=out[c+1];const area=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax);if(area>=-.12&&mat.side!==THREE.DoubleSide)continue;if(Math.abs(area)<.04)continue;const z=(out[a+2]+out[b+2]+out[c+2])/3;if(z<-.99||z>1||Math.max(ax,bx,cx)<0||Math.min(ax,bx,cx)>w||Math.max(ay,by,cy)<0||Math.min(ay,by,cy)>h)continue;let normalX=nm[0]*nx+nm[3]*ny+nm[6]*nz,normalY=nm[1]*nx+nm[4]*ny+nm[7]*nz,normalZ=nm[2]*nx+nm[5]*ny+nm[8]*nz;const len=Math.hypot(normalX,normalY,normalZ)||1;normalX/=len;normalY/=len;normalZ/=len;let shade=mat.isMeshBasicMaterial?1:.44+.54*Math.max(0,normalX*light.x+normalY*light.y+normalZ*light.z)+.13*Math.max(0,-normalX);const spec=Math.pow(Math.max(0,normalX*-.2+normalY*.32+normalZ*.93),20)*.13;const r=Math.min(255,Math.round(color.r*255*shade+spec*255)),gg=Math.min(255,Math.round(color.g*255*shade+spec*255)),bb=Math.min(255,Math.round(color.b*255*shade+spec*255));faces.push([z,ax,ay,bx,by,cx,cy,`rgb(${r},${gg},${bb})`,op]);}
 });faces.sort((a,b)=>b[0]-a[0]);ctx.setTransform(this.ratio,0,0,this.ratio,0,0);ctx.clearRect(0,0,w,h);ctx.lineJoin='round';ctx.lineWidth=.45;for(const f of faces){ctx.globalAlpha=f[8];ctx.fillStyle=f[7];ctx.beginPath();ctx.moveTo(f[1],f[2]);ctx.lineTo(f[3],f[4]);ctx.lineTo(f[5],f[6]);ctx.closePath();ctx.fill();if(f[8]>.9){ctx.strokeStyle=f[7];ctx.stroke()}}ctx.globalAlpha=1;
 }
}
